from taf.sbts.oam.coam.admin import admin
from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from taf.rfrl.procedures.resources.python.sw_stream.interface import get_sw_stream
from taf.rfrl.procedures.resources.python.sw_stream.sw_stream_names import \
    SW_MASTER, SW_22R4, SW_22R3, SW_23R1, SW_23R2, SW_23R3, SW_23R4, SW_24R1, SW_24R2, SW_24R3, SW_25R1, SW_25R2, SW_25R3, SW_26R1, SW_26R2


@log_input_and_output
def change_bts_rad_parameters(component, params, connection):
    """
    Change RAD parameters.
    :param params: RAD parameters string (parameter:value) eg. 34:5
    :type component: str
    :param component: BTS system component number
    :type component: str
    :param AdminConnection connection: AdminConnection object or if used, string name alias.
    :type component: str
    """
    adm = admin()
    adm.change_bts_rad_parameters(component=component,
                                  params=params,
                                  connection=connection)


@log_input_and_output
def rnd_mod_on(connection):
    """
    Switches on R&D mod.

    !!! This method must be used before logging into selenium with R&D Mode access expected. !!!

    :param AdminConnection connection: AdminConnection object or if used, string name alias.
    """
    _rnd_mod(connection, True)


@log_input_and_output
def rnd_mod_off(connection):
    """
    Switches off R&D mod

    :param AdminConnection connection: AdminConnection object or if used, string name alias.
    """
    _rnd_mod(connection, False)


@log_input_and_output
def _rnd_mod(connection, on):
    """
    :param AdminConnection connection: AdminConnection object or if used, string name alias.
    :param bool on:
    """
    adm = admin()
    sw_stream = get_sw_stream()
    params_index = "39" if sw_stream in (SW_MASTER,
                                         SW_26R2,
                                         SW_26R1,
                                         SW_25R3,
                                         SW_25R2,
                                         SW_25R1,
                                         SW_24R3,
                                         SW_24R2,
                                         SW_24R1,
                                         SW_23R4,
                                         SW_23R3,
                                         SW_23R2,
                                         SW_23R1,
                                         SW_22R4,
                                         SW_22R3) else "90"
    adm.change_bts_rad_parameters(component="69",
                                  params="{0}:{1}".format(params_index, 1 if on else 0),
                                  connection=connection)
